INSERT INTO "Flag" ("id", "labId", "position", "question", "hint", "answerHash", "value", "points", "createdAt", "updatedAt") VALUES ('b8cec75b-118b-4ae8-a3e9-1dbe78882847', 'f85ec687-5b86-40e2-a73b-5366652a4b10', 6, 'Navigate to the Path Traversal lesson. Enter: ../../../etc/passwd in the file input field. What system file content or error message is returned?', 'Enter ../../../etc/passwd in the Path Traversal file input', '$2b$10$Cb.Wv9PyQ9O/sP1unh6npeiloGlNUXe1yJ8Sj25iCGmNW.PPV3pLG', 'PATH_TRAVERSAL_EXPLOITED', 60, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Flag" ("id", "labId", "position", "question", "hint", "answerHash", "value", "points", "createdAt", "updatedAt") VALUES ('d0780dee-5226-482b-ac32-c3e6fd36c3ca', 'f85ec687-5b86-40e2-a73b-5366652a4b10', 7, 'Navigate to the JWT lesson. Decode the JWT token from the authorization header using a base64 decoder. What algorithm and payload data does the token contain?', 'Decode the JWT token payload from the authorization header', '$2b$10$maCWuvbNNqQT19iP/fHAjOV1003hsehavKiBd.6DYhCK3UXP/w3Wu', 'JWT_TOKEN_WEAKNESS', 70, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Flag" ("id", "labId", "position", "question", "hint", "answerHash", "value", "points", "createdAt", "updatedAt") VALUES ('74c3d39d-26e3-4ad9-b26b-94dcb897405c', 'f85ec687-5b86-40e2-a73b-5366652a4b10', 8, 'Navigate to the CORS lesson. Submit a request from a different origin. What response headers (Access-Control-Allow-Origin) are returned that indicate misconfigured CORS?', 'Check CORS response headers in the CORS lesson', '$2b$10$BhSRhOOyEj584XxcF0R1OOV.vwk747j0p2uOwzjhwnhAAVjlx67Ba', 'CORS_MISCONFIG_FOUND', 80, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Flag" ("id", "labId", "position", "question", "hint", "answerHash", "value", "points", "createdAt", "updatedAt") VALUES ('a0d358a5-ea24-4c11-8104-58444fe8046d', 'f85ec687-5b86-40e2-a73b-5366652a4b10', 9, 'Navigate to the DOM-Based XSS lesson. Enter: <img src=x onerror=alert(1)> in the input field. What JavaScript execution or alert is triggered in the browser?', 'Enter an img tag with onerror in the DOM XSS lesson', '$2b$10$HQVKBTWZhjJGGqSD2r0YCOWlFbut4co2ew9VHVflTqk28mOzQv496', 'DOM_XSS_TRIGGERED', 90, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Lab" ("id", "name", "slug", "description", "createdAt", "updatedAt") VALUES ('9c861331-b3f2-4322-94d5-bc64f312f46e', 'NodeGoat', 'nodegoat', 'OWASP NodeGoat Node.js vulnerable application on port 4000', NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Flag" ("id", "labId", "position", "question", "hint", "answerHash", "value", "points", "createdAt", "updatedAt") VALUES ('5e963509-3537-4058-aa34-996910b33e2e', '9c861331-b3f2-4322-94d5-bc64f312f46e', 1, 'Run: curl -sI http://localhost:4000. What Node.js version number is revealed in the X-Powered-By or Server response header?', 'curl -sI http://localhost:4000', '$2b$10$9UcXK72eAqA/tAnWAsXLR.XXi8/Y9WnrCcX.Vlsmam46kC9..P.tW', 'NODE_VERSION_LEAKED', 10, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Flag" ("id", "labId", "position", "question", "hint", "answerHash", "value", "points", "createdAt", "updatedAt") VALUES ('7689faaf-a2cf-46c1-89d0-47963ff6c0b1', '9c861331-b3f2-4322-94d5-bc64f312f46e', 2, 'Run: curl -X POST http://localhost:4000/api/contributions -H "Content-Type: application/json" -d {"userId":"1","amount":{"$gt":""}}. What contribution data is returned when using a NoSQL injection operator?', 'curl -X POST http://localhost:4000/api/contributions -H "Content-Type: application/json" -d {"userId":"1","amount":{"$gt":""}}', '$2b$10$TdaRseasOU5PgIr4VwYyV.UlfI7wnMht4cOn2d4j2BquZeSrjW2jS', 'NOSQL_INJECTION_EXPLOITED', 20, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Flag" ("id", "labId", "position", "question", "hint", "answerHash", "value", "points", "createdAt", "updatedAt") VALUES ('106f62bc-4ffa-4a9e-a685-fa8c222db050', '9c861331-b3f2-4322-94d5-bc64f312f46e', 3, 'Run: curl http://localhost:4000/api/contributions/1 and then curl http://localhost:4000/api/contributions/2. Can you access another user contribution by changing the ID parameter? What data is returned?', 'curl http://localhost:4000/api/contributions/1 && curl http://localhost:4000/api/contributions/2', '$2b$10$kGeVcVVZZPN83mlTyVJIueeI9sGB9cUp4/qlCRIwH4U5du4m2CWGW', 'IDOR_EXPLOITED', 30, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Flag" ("id", "labId", "position", "question", "hint", "answerHash", "value", "points", "createdAt", "updatedAt") VALUES ('9d9d3a01-fe7f-448c-ae1e-dbcd98e47dc6', '9c861331-b3f2-4322-94d5-bc64f312f46e', 4, 'Run: curl -X POST http://localhost:4000/api/contributions -H "Content-Type: application/json" -d {"userId":"1","amount":100} and then try {"userId":{"$ne":"1"},"amount":100}. What happens when injecting MongoDB operators in the userId field?', 'curl -X POST http://localhost:4000/api/contributions -H "Content-Type: application/json" -d {"userId":{"$ne":"1"},"amount":100}', '$2b$10$3awlxZmQ7.AqvxVH99PA.ebONzjkaRCDL9EeHdOuU.XUDnum4pq7G', 'MONGO_INJECTION_POINT', 40, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Flag" ("id", "labId", "position", "question", "hint", "answerHash", "value", "points", "createdAt", "updatedAt") VALUES ('07ddbf34-95c3-41eb-8f9e-b110c6eb44fd', '9c861331-b3f2-4322-94d5-bc64f312f46e', 5, 'Run: curl http://localhost:4000/api/contributions. What JSON data structure with user IDs and amounts is returned by the REST API?', 'curl http://localhost:4000/api/contributions', '$2b$10$4Pwah66Nkv2dPeJ7f6HKd.1KhAFW5TO//HbbYjBH.wV3tqlqdC.TC', 'REST_API_DATA_EXTRACTED', 50, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Flag" ("id", "labId", "position", "question", "hint", "answerHash", "value", "points", "createdAt", "updatedAt") VALUES ('e9916c20-3fa9-4519-87a6-4c009c6b3784', '9c861331-b3f2-4322-94d5-bc64f312f46e', 6, 'Log in to NodeGoat and check your browser cookies. Set the session cookie value to another logged-in user session. What happens when you access the profile page with a different session ID?', 'Modify the session cookie to another user session ID', '$2b$10$ujhWg5VQqd1LtnWc3MyQwO6OZs2/XjJH2UGd4IBLYo6l4Vd3zKOQG', 'SESSION_FIXATION_TESTED', 60, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Flag" ("id", "labId", "position", "question", "hint", "answerHash", "value", "points", "createdAt", "updatedAt") VALUES ('16db5866-34c4-4fe9-ae50-c99ff4087af0', '9c861331-b3f2-4322-94d5-bc64f312f46e', 7, 'Navigate to the Profile page. In the name field, enter: <script>alert(document.cookie)</script> and save the profile. When viewing the profile, what JavaScript alert or content is rendered?', 'Enter a script tag in the profile name field and view the profile', '$2b$10$zIVXoM39c3XYVreq63ItjOZ3vmVtSX9VxMydh6lBfT0CYgisvyN3u', 'XSS_IN_PROFILE_FOUND', 70, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Flag" ("id", "labId", "position", "question", "hint", "answerHash", "value", "points", "createdAt", "updatedAt") VALUES ('7ceaee2c-38bc-4026-bcf6-37ed3de596fa', '9c861331-b3f2-4322-94d5-bc64f312f46e', 8, 'Run: curl http://localhost:4000/api/contributions/1 -X PUT -H "Content-Type: application/json" -d {"userId":"1","amount":999999}. What response is returned when attempting to modify another user contribution?', 'curl http://localhost:4000/api/contributions/1 -X PUT -H "Content-Type: application/json" -d {"userId":"1","amount":999999}', '$2b$10$wlCpbk1OxWN5fT3P/dL7F.cd6MzImiZowLaNzJdXCfHzvNP0jj1FW', 'CONTRIBUTION_TAMPERED', 80, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Flag" ("id", "labId", "position", "question", "hint", "answerHash", "value", "points", "createdAt", "updatedAt") VALUES ('4f15618f-4533-4749-a512-5e2b154ef8d8', '9c861331-b3f2-4322-94d5-bc64f312f46e', 9, 'Run: curl http://localhost:4000/api/contributions?userId=1. What contribution amounts and user details are returned when querying with a specific userId parameter?', 'curl http://localhost:4000/api/contributions?userId=1', '$2b$10$9nwlp08Jj4C6I.Yzj9dC2e1q1nQtk4Z5jI1EGNMxb6SbZGRYJqp9u', 'CONTRIBUTOR_DATA_EXPOSED', 90, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
